SELECT hva.account_id, hva.account_name, hva.account_full_name, hva.account_num, hva.manufacturer_id, hva.tenant_id, hva.primary_flag, hva.is_auto_writeoff_flag, (select v.meaning value_name from sys_code_value_b_v v where v.code = 'SYS.YES_NO' and v.code_value = hva.is_auto_writeoff_flag) is_auto_writeoff_flag_n, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = hva.manufacturer_id) manufacturer_id_n, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = hva.tenant_id) tenant_id_n, hva.contract_id, cc.contract_number, cc.contract_number contract_id_n, hva.bank_code, (select cb.bank_name from csh_bank cb where cb.bank_code = hva.bank_code) bank_name, (select cb.bank_name from csh_bank cb where cb.bank_code = hva.bank_code) bank_code_n FROM hls_virtual_account hva left join con_contract cc on cc.contract_id = hva.contract_id
and hva.manufacturer_id = #{manufacturerId}
and hva.tenant_id = #{tenantId}
and hva.contract_id = #{contractId}
and hva.bank_code = #{bankCode}
and hva.account_full_name like concat('%',concat(#{accountFullName},'%'))
and hva.account_num like concat('%',concat(#{accountNum},'%'))
and cc.contract_number like concat('%',concat(#{contractNumber},'%'))
and hva.account_name like concat('%',concat(#{accountName},'%'))
and (select cb.bank_name from csh_bank cb where cb.bank_code = hva.bank_code) like concat('%',concat(#{bankName},'%'))

SELECT hva.account_id, hva.account_name, hva.account_full_name, hva.account_num, hva.manufacturer_id, hva.tenant_id, hva.primary_flag FROM hls_virtual_account hva
hva.tenant_id is null
and hva.manufacturer_id = #{manufacturerId}
